const today = new Date().toISOString().slice(0, 10);
const brands = ['dax-collective', 'dax-the-traveler', 'time-zone-travelers', 'ani-dax', 'gods-vessel'];
const outputTypes = ['posts', 'videos', 'itineraries', 'merch', 'stickers', 'designs'];

const brandOutputMap = {
  'dax-collective': ['posts', 'videos', 'designs'],
  'dax-the-traveler': ['posts', 'videos', 'itineraries', 'designs'],
  'time-zone-travelers': ['posts', 'videos', 'itineraries', 'stickers', 'designs'],
  'ani-dax': ['posts', 'videos', 'stickers', 'designs'],
  'gods-vessel': ['posts', 'videos', 'merch', 'stickers', 'designs']
};

const agentByOutput = {
  posts: 'social_post_agent',
  videos: 'video_concept_agent',
  itineraries: 'itinerary_agent',
  merch: 'merch_design_agent',
  stickers: 'sticker_design_agent',
  designs: 'brand_design_agent'
};

const tasks = [];
for (const brand of brands) {
  for (const outputType of brandOutputMap[brand]) {
    tasks.push({
      brand,
      outputType,
      primaryAgent: agentByOutput[outputType],
      qaAgent: 'compliance_qa_agent',
      publishAllowed: false,
      reviewStatus: 'manual_review_required',
      task: `Create one ${outputType} review package for ${brand}`,
      blocker: outputType === 'videos' ? 'review video can be generated locally; public upload blocked until account credentials exist' : 'draft can be created now; public publishing blocked until account credentials exist'
    });
  }
}

return [{
  json: {
    date: today,
    workflow: 'DAX-04 Company Startup Operator - Manual Review',
    operatingMode: 'manual_review_first',
    publishingEnabled: false,
    activeCompanyAgents: [
      'operations_director_agent',
      'content_strategy_agent',
      'social_post_agent',
      'video_concept_agent',
      'itinerary_agent',
      'merch_design_agent',
      'sticker_design_agent',
      'brand_design_agent',
      'asset_management_agent',
      'publishing_scheduler_agent',
      'analytics_agent',
      'revenue_agent',
      'community_agent',
      'compliance_qa_agent',
      'platform_setup_agent',
      'error_handler_agent'
    ],
    dailyTasks: tasks,
    immediateSafeRuns: [
      'Run DAX-00 for routing map.',
      'Run DAX-01 to create local review videos for all five brands.',
      'Run DAX-02 for operations brief.',
      'Run DAX-03 to track account blockers.'
    ],
    accountBlockers: [
      'Create Facebook Pages for each brand under the existing Facebook account.',
      'Create Instagram Business/Creator accounts and link each to the matching Facebook Page.',
      'Create TikTok brand accounts and developer app if API posting is required.',
      'Create/connect YouTube channels or Brand Accounts.',
      'Set up public n8n HTTPS callback URL before OAuth publishing workflows.'
    ],
    websiteModernizationQueue: [
      'Standardize Dax the Traveler page to the current modern layout language.',
      'Standardize Ani-Dax page to the current modern layout language.',
      'Standardize God\'s Vessel page to the current modern layout language.',
      'Add consistent hero/media/CTA sections and remove outdated placeholder patterns.',
      'Keep brand-specific colors and assets from the planning docs.'
    ],
    createdAt: new Date().toISOString()
  }
}];

const brief = $input.first().json;
const counts = brief.dailyTasks.reduce((acc, task) => {
  acc.byBrand[task.brand] = (acc.byBrand[task.brand] || 0) + 1;
  acc.byOutputType[task.outputType] = (acc.byOutputType[task.outputType] || 0) + 1;
  return acc;
}, { byBrand: {}, byOutputType: {} });

return [{
  json: {
    ...brief,
    taskCounts: counts,
    status: 'company_operating_brief_ready',
    nextAction: 'Review this brief, then run the safe workflows listed in immediateSafeRuns. Do not activate publisher workflows until account setup blockers are cleared.',
    reviewStatus: 'manual_review_required'
  }
}];
